.ore-name { color: var(--muted); font-size: 12.5px; letter-spacing: 0.03em; }
.gem { width: 8px; height: 8px; transform: rotate(45deg); display: block; border: 1px solid rgba(255, 255, 255, 0.2); }
.gem.ember { background: linear-gradient(135deg, #ffcf8f, #ff7a2f 55%, #9c3d12); box-shadow: 0 0 8px rgba(255, 122, 47, 0.7); }
.gem.gloam { background: linear-gradient(135deg, #c5f6ff, #52dcff 55%, #1c6f8d); box-shadow: 0 0 8px rgba(82, 220, 255, 0.7); }
.gem.blood { background: linear-gradient(135deg, #ffb0b4, #ff3d52 55%, #79121d); box-shadow: 0 0 8px rgba(255, 61, 82, 0.7); }
.gem.soul { background: linear-gradient(135deg, #f2e1ff, #c79bff 55%, #6a30a8); box-shadow: 0 0 8px rgba(199, 155, 255, 0.7); }
.ore-row.pulse b { animation: orePop 0.35s ease; }
@keyframes orePop { 50% { color: #fff; text-shadow: 0 0 12px currentColor; transform: scale(1.18); } }

#boss-bar {
  position: absolute; left: 50%; top: 6px; transform: translateX(-50%);
  width: min(440px, 42vw); padding: 10px 16px 12px;
  background: linear-gradient(180deg, rgba(20, 12, 30, 0.82), rgba(9, 6, 14, 0.6));
  border: 1px solid rgba(199, 155, 255, 0.24);
  box-shadow: 0 8px 40px rgba(90, 30, 160, 0.22);
  backdrop-filter: blur(8px);
}
.boss-name { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--display); font-size: 10px; letter-spacing: 0.27em; color: #d9c4ff; margin-bottom: 7px; }
.boss-name em { font-style: normal; font-size: 9px; letter-spacing: 0.1em; color: #9f8ab5; }

#crosshair { position: absolute; left: 50%; top: 50%; width: 34px; height: 34px; transform: translate(-50%, -50%); opacity: 0.85; transition: opacity 0.2s; }
.ch-dot { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; margin: -1.5px 0 0 -1.5px; background: #f4e7cb; box-shadow: 0 0 6px rgba(255, 225, 170, 0.9); border-radius: 50%; }
.ch-tick { position: absolute; background: rgba(232, 215, 180, 0.65); box-shadow: 0 0 5px rgba(0, 0, 0, 0.8); transition: all 0.18s ease; }
.ch-tick.t, .ch-tick.b { width: 1px; height: 6px; left: 50%; margin-left: -0.5px; }
.ch-tick.l, .ch-tick.r { height: 1px; width: 6px; top: 50%; margin-top: -0.5px; }
.ch-tick.t { top: 3px; } .ch-tick.b { bottom: 3px; } .ch-tick.l { left: 3px; } .ch-tick.r { right: 3px; }
.ch-ring { position: absolute; inset: 0; fill: none; stroke: rgba(255, 205, 130, 0.85); stroke-width: 1; opacity: 0; transform: rotate(-90deg); transition: opacity 0.2s; filter: drop-shadow(0 0 4px rgba(255, 160, 70, 0.5)); }
#crosshair.targeting .ch-tick.t { top: 0; } #crosshair.targeting .ch-tick.b { bottom: 0; }
#crosshair.targeting .ch-tick.l { left: 0; } #crosshair.targeting .ch-tick.r { right: 0; }
#crosshair.targeting .ch-ring { opacity: 0.9; }
#crosshair.targeting .ch-tick { background: #ffd9a0; }
#crosshair.hit { animation: chHit 0.18s ease; }
@keyframes chHit { 50% { transform: translate(-50%, -50%) scale(1.35); } }
#crosshair.hidden { display: none !important; }

#target-panel {
  position: absolute; left: 50%; top: calc(50% + 29px); transform: translateX(-50%);
  width: 208px; padding: 7px 10px 8px;
  background: linear-gradient(180deg, rgba(12, 12, 17, 0.78), rgba(7, 7, 10, 0.5));
  border: 1px solid rgba(201, 167, 95, 0.14);
  backdrop-filter: blur(5px);
}
.target-head { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; margin-bottom: 5px; }
#target-name { font-family: var(--display); font-size: 8px; letter-spacing: 0.16em; text-transform: uppercase; color: #e6dcc7; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#target-hp { font-style: normal; font-family: var(--display); font-size: 8px; color: var(--faint); letter-spacing: 0.05em; }
#target-panel .bar i { background: linear-gradient(90deg, #7c4a1e, #e0a04c); box-shadow: none; }

#interact-prompt {
  position: absolute; left: 50%; bottom: calc(104px + var(--safe-b)); transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px;
  padding: 9px 16px 9px 10px;
  background: linear-gradient(180deg, rgba(17, 16, 21, 0.88), rgba(8, 8, 11, 0.76));
  border: 1px solid rgba(201, 167, 95, 0.28);
  box-shadow: 0 6px 26px rgba(0, 0, 0, 0.4);
  font-size: 14px; color: #e7dcc4; letter-spacing: 0.03em;
  animation: promptIn 0.22s ease both;
  backdrop-filter: blur(6px);
}
#interact-prompt kbd { font-size: 10px; padding: 5px 8px 4px; background: rgba(201, 167, 95, 0.13); }
#interact-prompt.sealed { border-color: rgba(126, 126, 140, 0.24); color: var(--muted); }
#interact-prompt.sealed kbd { color: var(--muted); border-color: rgba(126, 126, 140, 0.24); }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 6px); } to { opacity: 1; transform: translate(-50%, 0); } }

#hud-health {
  position: absolute; left: calc(22px + var(--safe-l)); bottom: calc(22px + var(--safe-b));
  width: 276px; padding: 10px 14px 12px;
}
.health-label { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--display); font-size: 8px; letter-spacing: 0.24em; color: var(--muted); margin-bottom: 7px; }
.health-label span:last-child { color: #e2c2ad; font-size: 8px; letter-spacing: 0.1em; }
#hud-health.critical .bar.health i { animation: healthPulse 0.8s ease infinite; }
@keyframes healthPulse { 50% { filter: brightness(1.65); } }

#hint-strip {
  position: absolute; right: calc(22px + var(--safe-r)); bottom: calc(24px + var(--safe-b));
  display: flex; flex-direction: column; align-items: flex-end; gap: 6px;
  font-size: 11px; color: rgba(147, 139, 125, 0.62); letter-spacing: 0.04em;
}
#hint-strip span { display: flex; align-items: center; gap: 6px; }
#hint-strip kbd { opacity: 0.6; }

#toasts {
  position: absolute; right: calc(24px + var(--safe-r)); top: 39%;
  display: flex; flex-direction: column; align-items: flex-end; gap: 7px;
  pointer-events: none; max-width: 280px;
}
.toast {
  display: flex; align-items: center; gap: 9px;
  padding: 8px 14px 8px 11px;
  background: linear-gradient(90deg, rgba(14, 13, 18, 0.92), rgba(14, 13, 18, 0.55));
  border-left: 2px solid var(--gold);
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  font-size: 13.5px; color: #e6dcc7; letter-spacing: 0.02em;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.3);
  animation: toastIn 0.28s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  text-align: right;
}
.toast .gem { flex: none; }
.toast.out { animation: toastOut 0.35s ease both; }
.toast.gold { border-left-color: var(--gold); }
.toast.warn { border-left-color: #a36f45; color: #cbb69c; }
.toast.danger { border-left-color: var(--danger); color: #e7b9b0; }
.toast.arcane { border-left-color: var(--soul); color: #ddc8f5; }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px); } to { opacity: 1; transform: translateX(0); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(12px); } }

#objective-toast {
  position: absolute; left: 50%; top: 21%; transform: translateX(-50%);
  width: min(560px, 84vw); text-align: center; pointer-events: none;
  font-family: var(--display); text-transform: uppercase;
  font-size: clamp(11px, 1.4vw, 14px); letter-spacing: 0.3em; color: var(--gold-bright);
  text-shadow: 0 2px 18px #000, 0 0 26px rgba(255, 150, 60, 0.18);
  opacity: 0; transition: opacity 0.5s ease;
}
#objective-toast.show { opacity: 1; }
#objective-toast small { display: block; margin-top: 8px; font-family: var(--serif); font-style: italic; font-size: 14px; letter-spacing: 0.04em; text-transform: none; color: var(--muted); }

/* touch controls */
#mobile-controls { display: none; position: absolute; inset: 0; pointer-events: none; }
.is-touch #mobile-controls { display: block; }
#joystick {
  position: absolute; left: calc(24px + var(--safe-l)); bottom: calc(28px + var(--safe-b));
  width: 118px; height: 118px; border-radius: 50%;
  border: 1px solid rgba(201, 167, 95, 0.24);
  background: radial-gradient(circle at 50% 45%, rgba(201, 167, 95, 0.09), rgba(5, 5, 8, 0.32) 70%);
  box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.5), 0 0 0 6px rgba(0, 0, 0, 0.12);
  pointer-events: auto; touch-action: none;
}
.joy-ring { position: absolute; inset: 14px; border-radius: 50%; border: 1px dashed rgba(201, 167, 95, 0.13); }
#joystick-thumb {
  position: absolute; left: 50%; top: 50%; width: 50px; height: 50px; margin: -25px 0 0 -25px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, rgba(232, 207, 148, 0.32), rgba(90, 72, 44, 0.28) 62%, rgba(30, 27, 22, 0.55));
  border: 1px solid rgba(232, 207, 148, 0.36);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.45), inset 0 0 14px rgba(255, 210, 140, 0.1);
  transition: transform 0.05s linear;
}
.joy-label { position: absolute; left: 50%; bottom: -17px; transform: translateX(-50%); font-family: var(--display); font-size: 7px; letter-spacing: 0.3em; color: rgba(201, 167, 95, 0.4); }
.touch-btn {
  position: absolute; pointer-events: auto; touch-action: none;
  display: grid; place-items: center; border-radius: 50%;
  border: 1px solid rgba(232, 207, 148, 0.3);
  background: radial-gradient(circle at 45% 38%, rgba(201, 167, 95, 0.16), rgba(9, 9, 13, 0.7) 70%);
  color: var(--gold-bright); font-family: var(--display); font-size: 9px; letter-spacing: 0.16em;
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.45), inset 0 0 18px rgba(255, 180, 90, 0.06);
  transition: transform 0.08s, background 0.08s;
}
.touch-btn:active, .touch-btn.pressed { transform: scale(0.94); background: radial-gradient(circle at 45% 38%, rgba(255, 160, 70, 0.34), rgba(20, 12, 8, 0.75) 72%); }
#btn-mine {
  right: calc(26px + var(--safe-r)); bottom: calc(34px + var(--safe-b));
  width: 94px; height: 94px;
  border-color: rgba(255, 150, 70, 0.42);
  box-shadow: 0 0 40px rgba(255, 120, 40, 0.12), inset 0 0 24px rgba(255, 130, 50, 0.1);
}
#btn-mine svg { width: 34px; height: 34px; fill: none; stroke: #ffcf95; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; margin-bottom: -2px; filter: drop-shadow(0 0 5px rgba(255, 150, 60, 0.45)); }
#btn-mine span { font-size: 8px; letter-spacing: 0.24em; color: rgba(255, 207, 149, 0.75); }
#btn-interact { right: calc(38px + var(--safe-r)); bottom: calc(146px + var(--safe-b)); width: 62px; height: 62px; font-size: 8px; }
#btn-jump { right: calc(118px + var(--safe-r)); bottom: calc(150px + var(--safe-b)); width: 54px; height: 54px; font-size: 7px; }
#btn-pause { pointer-events: auto; }
.mobile-only { display: none; }
.mobile-pause-wrap { display: none; }

/* ── forge ───────────────────────────────────────────────────── */
#forge-screen { z-index: 55; }
.forge-panel {
  position: relative; width: min(980px, calc(100vw - 32px)); max-height: min(92dvh, 920px);
  display: flex; flex-direction: column;
  padding: 28px 30px 20px;
  background:
    radial-gradient(ellipse at 50% -10%, rgba(255, 138, 60, 0.1), transparent 55%),
    linear-gradient(160deg, #17141a 0%, #0e0d12 54%, #09090c 100%);
  border: 1px solid rgba(201, 167, 95, 0.3);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.7), inset 0 0 80px rgba(0, 0, 0, 0.35);
}
.forge-panel::before {
  content: ''; position: absolute; inset: 7px; pointer-events: none;
  border: 1px solid rgba(201, 167, 95, 0.1);
}
.forge-panel::after {
  content: ''; position: absolute; left: 50%; top: -1px; transform: translateX(-50%);
  width: 90px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold), transparent);
}
.forge-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; padding-bottom: 16px; position: relative; z-index: 1; }
.forge-head .eyebrow { margin-bottom: 8px; }
.forge-head h2 { font-family: var(--display); font-weight: 400; font-size: clamp(1.5rem, 3.4vw, 2.2rem); letter-spacing: 0.03em; margin: 0 0 6px; color: #f0e6d0; }
.forge-sub { margin: 0; color: var(--faint); font-size: 14px; font-style: italic; }
.wallet { display: flex; flex-wrap: wrap; gap: 10px 22px; padding: 12px 2px 16px; border-top: 1px solid var(--line-soft); border-bottom: 1px solid var(--line-soft); margin-bottom: 16px; position: relative; z-index: 1; }
.wallet .w-item { display: flex; align-items: center; gap: 8px; font-size: 14px; color: var(--muted); }
.wallet .w-item b { font-family: var(--display); font-weight: 400; font-size: 12px; color: #f0e4cd; letter-spacing: 0.05em; }
.upgrade-list { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; overflow-y: auto; padding: 2px 4px 8px 2px; scrollbar-width: thin; scrollbar-color: rgba(201, 167, 95, 0.28) transparent; position: relative; z-index: 1; }
.upgrade-card {
  display: grid; grid-template-columns: 44px 1fr 134px; gap: 12px; align-items: center;
  padding: 12px 13px;
  background: linear-gradient(150deg, rgba(30, 27, 34, 0.72), rgba(14, 13, 17, 0.7));
  border: 1px solid rgba(201, 167, 95, 0.13);
  transition: border-color 0.25s, background 0.25s;
}
.upgrade-card:hover { border-color: rgba(201, 167, 95, 0.32); background: linear-gradient(150deg, rgba(36, 32, 40, 0.8), rgba(16, 15, 20, 0.8)); }
.upgrade-card.maxed { border-color: rgba(201, 167, 95, 0.3); background: linear-gradient(150deg, rgba(45, 36, 24, 0.4), rgba(15, 14, 17, 0.7)); }
.upgrade-icon {
  width: 44px; height: 44px; display: grid; place-items: center;
  border: 1px solid rgba(201, 167, 95, 0.22); border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, rgba(201, 167, 95, 0.12), transparent 65%);
  color: var(--gold);
}
.upgrade-icon svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
.upgrade-title { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.upgrade-title h3 { margin: 0; font-family: var(--display); font-weight: 400; font-size: 13px; letter-spacing: 0.06em; color: #eadfc9; }
.pips { display: flex; gap: 3px; flex: none; }
.pips i { width: 5px; height: 5px; transform: rotate(45deg); border: 1px solid rgba(201, 167, 95, 0.42); }
.pips i.on { background: var(--gold); border-color: var(--gold); box-shadow: 0 0 6px rgba(201, 167, 95, 0.55); }
.upgrade-desc { margin: 3px 0 4px; font-size: 12px; color: var(--faint); line-height: 1.3; }
.upgrade-effect { margin: 0; font-size: 13px; color: #c9bfa9; letter-spacing: 0.01em; }
.upgrade-effect em { color: var(--gold-bright); font-style: normal; }
.upgrade-buy { display: flex; flex-direction: column; align-items: flex-end; gap: 7px; }
.cost { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 5px 9px; font-size: 11px; }
.cost span { display: inline-flex; align-items: center; gap: 4px; color: #bdb3a0; white-space: nowrap; }
.cost span.lack { color: #8a5a52; }
.cost .gem { width: 6px; height: 6px; }
.btn-buy {
  font-family: var(--display); font-size: 8px; letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--gold-bright); border: 1px solid rgba(201, 167, 95, 0.36);
  padding: 7px 13px 6px; background: rgba(201, 167, 95, 0.08);
  transition: all 0.2s;
}
.btn-buy:hover:not(:disabled) { background: var(--gold); color: #151007; }
.btn-buy:disabled { opacity: 0.35; cursor: default; }
.upgrade-card.maxed .btn-buy { border-color: rgba(201, 167, 95, 0.5); color: var(--gold); opacity: 1; }
.forge-foot { display: flex; justify-content: space-between; align-items: center; padding-top: 14px; font-size: 11px; color: var(--faint); letter-spacing: 0.06em; position: relative; z-index: 1; }
.forge-foot kbd { margin-right: 4px; }
.forge-note { font-style: italic; color: rgba(201, 167, 95, 0.42); }

/* ── dialogs / endings ───────────────────────────────────────── */
.dialog {
  position: relative; width: min(540px, calc(100vw - 32px));
  padding: 40px 40px 32px; text-align: center;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(201, 167, 95, 0.09), transparent 55%),
    linear-gradient(160deg, #17141a, #0a090d);
  border: 1px solid rgba(201, 167, 95, 0.3);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.75);
}
.dialog::before { content: ''; position: absolute; inset: 7px; border: 1px solid rgba(201, 167, 95, 0.1); pointer-events: none; }
.dialog::after {
  content: ''; position: absolute; left: 50%; top: -4px; width: 8px; height: 8px; transform: translateX(-50%) rotate(45deg);
  background: var(--gold); box-shadow: 0 0 16px rgba(201, 167, 95, 0.7);
}
.dialog h2 { position: relative; font-family: var(--display); font-weight: 400; font-size: clamp(1.8rem, 5vw, 2.6rem); letter-spacing: 0.05em; margin: 0 0 12px; color: #f1e6cf; }
.dialog-sub { color: var(--muted); line-height: 1.55; font-size: 15px; margin: 0 0 22px; }
.dialog .btn { display: flex; width: 100%; }
.dialog .btn-ghost { margin-top: 9px; }
.pause-controls { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px 16px; margin-top: 24px; padding-top: 16px; border-top: 1px solid var(--line-soft); font-size: 11px; color: var(--faint); }
.pause-controls span { display: flex; gap: 5px; align-items: center; }
.death-dialog { background: radial-gradient(ellipse at 50% 0%, rgba(150, 24, 20, 0.14), transparent 55%), linear-gradient(160deg, #1b1417, #0a080a); border-color: rgba(224, 86, 79, 0.25); }
.death-dialog::after { background: var(--danger); box-shadow: 0 0 16px rgba(224, 86, 79, 0.7); }
.victory-dialog {
  background:
    radial-gradient(ellipse at 50% 0%, rgba(255, 200, 110, 0.17), transparent 60%),
    linear-gradient(160deg, #1b1812, #0a0907);
  border-color: rgba(255, 210, 130, 0.4);
}
.victory-dialog h2 { color: #ffe7b4; text-shadow: 0 0 36px rgba(255, 180, 80, 0.3); }
.run-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: rgba(201, 167, 95, 0.12); border: 1px solid rgba(201, 167, 95, 0.12); margin: 0 0 22px; text-align: left; }
.run-stats div { background: #0e0d12; padding: 10px 13px; }
.run-stats span { display: block; font-family: var(--display); font-size: 7px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--faint); margin-bottom: 3px; }
.run-stats b { font-family: var(--display); font-weight: 400; font-size: 13px; color: #e5d8be; letter-spacing: 0.03em; }

/* ── transition ──────────────────────────────────────────────── */
#transition-veil {
  position: fixed; inset: 0; z-index: 80; display: grid; place-items: center; text-align: center;
  background: radial-gradient(ellipse at 50% 50%, #0b0a10 0%, #040406 70%);
  opacity: 0; pointer-events: none; transition: opacity 0.45s ease;
}
#transition-veil.active { opacity: 1; pointer-events: auto; }
.transition-inner { padding: 20px; transform: translateY(8px); opacity: 0; transition: opacity 0.5s 0.1s, transform 0.6s 0.1s; }
#transition-veil.active .transition-inner { opacity: 1; transform: translateY(0); }
.transition-rule { display: flex; align-items: center; justify-content: center; gap: 12px; width: 210px; margin: 0 auto 18px; }
.transition-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, var(--gold-dim)); }
.transition-rule i:last-child { background: linear-gradient(90deg, var(--gold-dim), transparent); }
.transition-rule b { width: 6px; height: 6px; transform: rotate(45deg); border: 1px solid var(--gold); }
#transition-depth { font-family: var(--display); font-size: 10px; letter-spacing: 0.55em; color: var(--gold); margin-bottom: 12px; }
#transition-name { font-family: var(--display); font-size: clamp(1.8rem, 5vw, 3rem); letter-spacing: 0.06em; color: #efe4cd; }
#transition-motto { margin: 12px 0 0; font-style: italic; color: var(--faint); font-size: 15px; }

#fatal { position: fixed; inset: 0; z-index: 100; display: grid; place-items: center; background: #07070a; }

/* ── responsive ──────────────────────────────────────────────── */
@media (max-width: 1020px) {
  .upgrade-list { grid-template-columns: 1fr; }
  .upgrade-card { grid-template-columns: 44px 1fr 130px; }
}

@media (max-width: 760px), (pointer: coarse) {
  body { font-size: 16px; }
  .desktop-hint { display: none !important; }
  #hint-strip { display: none; }
  #hud-health { width: min(44vw, 230px); left: calc(12px + var(--safe-l)); bottom: calc(14px + var(--safe-b)); padding: 8px 10px 9px; }
  .health-label { font-size: 7px; margin-bottom: 5px; }
  .health-label span:last-child { font-size: 7px; }
  .hud-top { top: calc(10px + var(--safe-t)); left: calc(10px + var(--safe-l)); right: calc(10px + var(--safe-r)); gap: 8px; }
  #depth-panel { min-width: 0; flex: 1; padding: 9px 11px 10px; max-width: calc(100% - 106px); }
  .depth-kicker { font-size: 6.5px; gap: 5px; }
  .depth-kicker b { font-size: 7.5px; padding: 1px 4px; }
  #depth-name { font-size: 13px; margin: 3px 0 0; letter-spacing: 0.03em; }
  .depth-motto { display: none; }
  .tithe { margin-top: 7px; }
  .tithe-label { font-size: 6.5px; margin-bottom: 4px; }
  .tithe-label span:last-child { font-size: 7.5px; }
  .bar { height: 5px; }
  #ore-panel { min-width: 0; width: 96px; padding: 8px 9px; gap: 4px; flex: none; }
  .ore-row { grid-template-columns: 8px 1fr; gap: 5px; }
  .ore-name { display: none; }
