import * as THREE from 'three';
import { mulberry32, TAU } from './utils.js';

function hash2(x, y, seed) {
  let h = Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(seed, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967295;
}

function fade(t) {
  return t * t * (3 - 2 * t);
}

function tileNoise(x, y, period, seed) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = fade(xf);
  const v = fade(yf);
  const x0 = ((xi % period) + period) % period;
  const y0 = ((yi % period) + period) % period;
  const x1 = (x0 + 1) % period;
  const y1 = (y0 + 1) % period;
  const a = hash2(x0, y0, seed);
  const b = hash2(x1, y0, seed);
  const c = hash2(x0, y1, seed);
  const d = hash2(x1, y1, seed);
  return (a * (1 - u) + b * u) * (1 - v) + (c * (1 - u) + d * u) * v;
}

function fbm(x, y, seed, octaves = 5, period = 6) {
  let value = 0;
  let amp = 0.5;
  let freq = period;
  let norm = 0;
  for (let i = 0; i < octaves; i += 1) {
    value += tileNoise(x * freq, y * freq, freq, seed + i * 97) * amp;
    norm += amp;
    amp *= 0.5;
    freq *= 2;
  }
  return value / norm;
}

function canvas2d(size) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  return { canvas, ctx: canvas.getContext('2d', { willReadFrequently: true }) };
}

function makeTexture(canvas, { repeat = true, srgb = true } = {}) {
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = repeat ? THREE.RepeatWrapping : THREE.ClampToEdgeWrapping;
  texture.wrapT = repeat ? THREE.RepeatWrapping : THREE.ClampToEdgeWrapping;
  texture.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  texture.anisotropy = 4;
  texture.needsUpdate = true;
  return texture;
}

function drawCracks(ctx, rng, size, count, color, glow = false) {
  ctx.save();
  for (let c = 0; c < count; c += 1) {
    let x = rng() * size;
    let y = rng() * size;
    let angle = rng() * TAU;
    const segments = 5 + Math.floor(rng() * 9);
    const width = 0.7 + rng() * 1.5;
    ctx.beginPath();
    ctx.moveTo(x, y);
    for (let i = 0; i < segments; i += 1) {
      angle += (rng() - 0.5) * 1.15;
      const step = 7 + rng() * 23;
      x += Math.cos(angle) * step;
      y += Math.sin(angle) * step;
      ctx.lineTo(x, y);
      if (rng() > 0.7) {
        const bx = x;
        const by = y;
        const ba = angle + (rng() - 0.5) * 1.8;
        ctx.moveTo(x, y);
        for (let j = 0; j < 3; j += 1) {
          ctx.lineTo(bx + Math.cos(ba + j * 0.4) * (4 + rng() * 12), by + Math.sin(ba + j * 0.4) * (4 + rng() * 12));
        }
        ctx.moveTo(x, y);
      }
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    if (glow) {
      ctx.shadowBlur = 8;
      ctx.shadowColor = color;
    }
    ctx.stroke();
  }
  ctx.restore();
}

function buildRock(size, seed, baseValue, variation, cracks, tint) {
  const color = canvas2d(size);
  const bump = canvas2d(size);
  const rng = mulberry32(seed);
  const colorData = color.ctx.createImageData(size, size);
  const bumpData = bump.ctx.createImageData(size, size);

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const i = (y * size + x) * 4;
      const nx = x / size;
      const ny = y / size;
      const broad = fbm(nx, ny, seed, 5, 5);
      const detail = fbm(nx, ny, seed + 311, 4, 23);
      const grit = hash2(x, y, seed + 17);
      const n = broad * 0.68 + detail * 0.32;
      let value = baseValue + (n - 0.5) * variation + (grit - 0.5) * 17;
      value = Math.max(0, Math.min(255, value));
      colorData.data[i] = Math.min(255, value * tint[0]);
      colorData.data[i + 1] = Math.min(255, value * tint[1]);
      colorData.data[i + 2] = Math.min(255, value * tint[2]);
      colorData.data[i + 3] = 255;
      const b = Math.max(0, Math.min(255, 96 + (n - 0.5) * 230 + (grit - 0.5) * 40));
      bumpData.data[i] = b;
      bumpData.data[i + 1] = b;
      bumpData.data[i + 2] = b;
      bumpData.data[i + 3] = 255;
    }
  }
  color.ctx.putImageData(colorData, 0, 0);
  bump.ctx.putImageData(bumpData, 0, 0);

  drawCracks(color.ctx, rng, size, cracks, 'rgba(8, 7, 10, 0.62)');
  drawCracks(color.ctx, rng, size, Math.max(2, cracks - 3), 'rgba(210, 200, 190, 0.08)');
  drawCracks(bump.ctx, mulberry32(seed + 99), size, cracks, 'rgba(0, 0, 0, 0.85)');

  const speckRng = mulberry32(seed + 41);
  for (let i = 0; i < size * 2.2; i += 1) {
    const x = speckRng() * size;
    const y = speckRng() * size;
    const r = 0.4 + speckRng() * 1.7;
    const v = 120 + speckRng() * 90;
    color.ctx.fillStyle = `rgba(${v}, ${v * 0.97}, ${v * 0.9}, ${0.16 + speckRng() * 0.2})`;
    color.ctx.beginPath();
    color.ctx.arc(x, y, r, 0, TAU);
    color.ctx.fill();
  }

  return { color: color.canvas, bump: bump.canvas };
}

export function createRockTextures() {
  const rock = buildRock(512, 7, 148, 112, 16, [1.0, 0.98, 0.95]);
  const ground = buildRock(512, 23, 122, 96, 22, [0.97, 0.96, 0.94]);
  return {
    rock: makeTexture(rock.color),
    rockBump: makeTexture(rock.bump, { srgb: false }),
    ground: makeTexture(ground.color),
    groundBump: makeTexture(ground.bump, { srgb: false }),
  };
}

export function createGlowTexture(size = 128) {
  const { canvas, ctx } = canvas2d(size);
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.18, 'rgba(255,255,255,0.85)');
  g.addColorStop(0.45, 'rgba(255,255,255,0.28)');
  g.addColorStop(0.75, 'rgba(255,255,255,0.06)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  return makeTexture(canvas, { repeat: false });
}

export function createSoftTexture(size = 64) {
  const { canvas, ctx } = canvas2d(size);
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,0.95)');
  g.addColorStop(0.5, 'rgba(255,255,255,0.3)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  return makeTexture(canvas, { repeat: false });
}

export function createRuneTexture(size = 512) {
  const { canvas, ctx } = canvas2d(size);
  const c = size / 2;
  ctx.clearRect(0, 0, size, size);

  const glow = ctx.createRadialGradient(c, c, 0, c, c, c);
  glow.addColorStop(0, 'rgba(255,255,255,0.5)');
  glow.addColorStop(0.44, 'rgba(255,255,255,0.16)');
  glow.addColorStop(0.72, 'rgba(255,255,255,0.05)');
  glow.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, size, size);

  ctx.strokeStyle = 'rgba(255,255,255,0.72)';
  ctx.lineWidth = 2;
  ctx.shadowBlur = 12;
  ctx.shadowColor = 'rgba(255,255,255,0.85)';
  for (const r of [0.94, 0.9, 0.66, 0.6]) {
    ctx.beginPath();
    ctx.arc(c, c, c * r, 0, TAU);
    ctx.stroke();
  }
  ctx.lineWidth = 1;
  ctx.strokeStyle = 'rgba(255,255,255,0.26)';
  for (let i = 0; i < 72; i += 1) {
    const a = (i / 72) * TAU;
    ctx.beginPath();
    ctx.moveTo(c + Math.cos(a) * c * 0.66, c + Math.sin(a) * c * 0.66);
    ctx.lineTo(c + Math.cos(a) * c * 0.9, c + Math.sin(a) * c * 0.9);
    ctx.stroke();
  }

  const rng = mulberry32(91);
  ctx.strokeStyle = 'rgba(255,255,255,0.9)';
  ctx.lineWidth = 2.2;
  ctx.shadowBlur = 10;
  ctx.shadowColor = 'rgba(255,255,255,0.9)';
  for (let i = 0; i < 18; i += 1) {
    const a = (i / 18) * TAU;
    ctx.save();
    ctx.translate(c + Math.cos(a) * c * 0.78, c + Math.sin(a) * c * 0.78);
    ctx.rotate(a + Math.PI / 2);
    ctx.beginPath();
    const glyph = Math.floor(rng() * 5);
    if (glyph === 0) {
      ctx.moveTo(-7, -9); ctx.lineTo(7, -9); ctx.lineTo(0, 9); ctx.closePath();
    } else if (glyph === 1) {
      ctx.moveTo(0, -10); ctx.lineTo(0, 10); ctx.moveTo(-7, -3); ctx.lineTo(7, 3);
    } else if (glyph === 2) {
      ctx.moveTo(-7, -8); ctx.lineTo(0, 0); ctx.lineTo(-7, 8); ctx.moveTo(1, -8); ctx.lineTo(8, 0); ctx.lineTo(1, 8);
    } else if (glyph === 3) {
      ctx.arc(0, 0, 7, 0, Math.PI * 1.4); ctx.moveTo(0, -10); ctx.lineTo(0, 10);
    } else {
      ctx.moveTo(-8, -8); ctx.lineTo(8, -8); ctx.moveTo(-8, 8); ctx.lineTo(8, 8); ctx.moveTo(0, -10); ctx.lineTo(0, 10);
    }
    ctx.stroke();
    ctx.restore();
  }

  const rng2 = mulberry32(52);
  for (let i = 0; i < 130; i += 1) {
    const a = rng2() * TAU;
    const r = Math.sqrt(rng2()) * c * 0.92;
    const s = 0.6 + rng2() * 2.2;
    ctx.fillStyle = `rgba(255,255,255,${0.15 + rng2() * 0.45})`;
    ctx.beginPath();
    ctx.arc(c + Math.cos(a) * r, c + Math.sin(a) * r, s, 0, TAU);
    ctx.fill();
  }
  return makeTexture(canvas, { repeat: false });
}

export function createCrackTexture(size = 256) {
  const { canvas, ctx } = canvas2d(size);
  const rng = mulberry32(77);
  ctx.clearRect(0, 0, size, size);
  ctx.strokeStyle = 'rgba(255,255,255,0.9)';
  ctx.lineCap = 'round';
  ctx.shadowBlur = 16;
  ctx.shadowColor = 'rgba(255,255,255,0.9)';
  for (let c = 0; c < 3; c += 1) {
    let x = rng() * size;
    let y = size * 0.5;
    let a = (rng() - 0.5) * 0.4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineWidth = 2.4;
    for (let i = 0; i < 16; i += 1) {
      a += (rng() - 0.5) * 0.8;
      x += Math.cos(a) * 11;
      y += (rng() - 0.5) * 16;
      ctx.lineTo(x, y);
      if (rng() > 0.78) {
        ctx.stroke();
        ctx.beginPath();
        ctx.lineWidth = 1;
        ctx.moveTo(x, y);
        ctx.lineTo(x + (rng() - 0.5) * 40, y + (rng() - 0.5) * 30);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineWidth = 2.4;
      }
    }
    ctx.stroke();
  }
  return makeTexture(canvas, { repeat: false });
}

export function createWoodTexture(size = 256) {
  const { canvas, ctx } = canvas2d(size);
  const rng = mulberry32(5);
  ctx.fillStyle = '#2a211b';
  ctx.fillRect(0, 0, size, size);
  for (let i = 0; i < 110; i += 1) {
    const y = rng() * size;
    const v = 22 + rng() * 34;
    ctx.strokeStyle = `rgba(${v + 12}, ${v + 4}, ${v - 4}, ${0.15 + rng() * 0.3})`;
    ctx.lineWidth = 0.5 + rng() * 2;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.bezierCurveTo(size * 0.3, y + (rng() - 0.5) * 8, size * 0.7, y + (rng() - 0.5) * 8, size, y + (rng() - 0.5) * 6);
    ctx.stroke();
  }
  return makeTexture(canvas, { repeat: true });
}

export function createTextures() {
  const rock = createRockTextures();
  return {
    ...rock,
    glow: createGlowTexture(128),
    soft: createSoftTexture(64),
    rune: createRuneTexture(512),
    crack: createCrackTexture(256),
    wood: createWoodTexture(256),
  };
}

// Procedural dark-fantasy soundscape and effects. No external audio assets.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.dry = null;
    this.wet = null;
    this.noiseBuffer = null;
    this.reverb = null;
    this.enabled = true;
    this.started = false;
    this.ambient = null;
    this.dripTimer = 4;
    this.heartTimer = 0;
    try {
      this.enabled = localStorage.getItem('gloamvein.sound') !== 'off';
    } catch {
      this.enabled = true;
    }
  }

  setEnabled(value) {
    this.enabled = value;
    try {
      localStorage.setItem('gloamvein.sound', value ? 'on' : 'off');
    } catch {}
    if (!this.ctx) {
      if (value) this.start();
      return;
    }
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setTargetAtTime(value ? 0.72 : 0.0001, now, 0.15);
    if (value) this.ctx.resume().catch(() => {});
  }

  toggle() {
    this.setEnabled(!this.enabled);
    return this.enabled;
  }

  start() {
    if (!this.enabled) return;
    if (this.ctx) {
      this.ctx.resume().catch(() => {});
      return;
    }
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.72;
      const compressor = this.ctx.createDynamicsCompressor();
      compressor.threshold.value = -18;
      compressor.knee.value = 22;
      compressor.ratio.value = 5;
      compressor.attack.value = 0.005;
      compressor.release.value = 0.28;
      this.master.connect(compressor);
      compressor.connect(this.ctx.destination);

      this.dry = this.ctx.createGain();
      this.dry.gain.value = 0.85;
      this.dry.connect(this.master);

      this.reverb = this.makeReverb(2.8);
      this.wet = this.ctx.createGain();
      this.wet.gain.value = 0.32;
      this.wet.connect(this.reverb);
      this.reverb.connect(this.master);

      this.noiseBuffer = this.makeNoise(2.0);
      this.started = true;
      this.startAmbient();
      this.ctx.resume().catch(() => {});
    } catch (error) {
      console.warn('Audio unavailable', error);
      this.ctx = null;
    }
  }

  makeNoise(seconds) {
    const rate = this.ctx.sampleRate;
    const buffer = this.ctx.createBuffer(1, rate * seconds, rate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < data.length; i += 1) {
      const white = Math.random() * 2 - 1;
      last = last * 0.96 + white * 0.04;
      data[i] = last * 3.2;
    }
    return buffer;
  }

  makeReverb(seconds) {
    const rate = this.ctx.sampleRate;
    const length = Math.floor(rate * seconds);
    const impulse = this.ctx.createBuffer(2, length, rate);
    for (let channel = 0; channel < 2; channel += 1) {
      const data = impulse.getChannelData(channel);
      for (let i = 0; i < length; i += 1) {
        const t = i / length;
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 2.8) * (1 - t * 0.25);
      }
    }
    const convolver = this.ctx.createConvolver();
    convolver.buffer = impulse;
    return convolver;
  }

  startAmbient() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const amb = ctx.createGain();
    amb.gain.value = 0.0001;
    amb.gain.setTargetAtTime(0.55, ctx.currentTime, 1.6);
    amb.connect(this.master);

    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 210;
    filter.Q.value = 0.9;
    filter.connect(amb);

    const freqs = [41.2, 55, 82.4, 61.7];
    const oscs = freqs.map((freq, index) => {
      const osc = ctx.createOscillator();
      osc.type = index % 2 === 0 ? 'sine' : 'triangle';
      osc.frequency.value = freq;
      osc.detune.value = (index - 1.5) * 4.5;
      const gain = ctx.createGain();
      gain.gain.value = index === 0 ? 0.16 : 0.045;
      osc.connect(gain);
      gain.connect(filter);
      osc.start();
      return { osc, gain };
    });

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.037;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 86;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    lfo.start();

    const air = ctx.createBufferSource();
    air.buffer = this.noiseBuffer;
    air.loop = true;
    const airFilter = ctx.createBiquadFilter();
    airFilter.type = 'bandpass';
    airFilter.frequency.value = 330;
    airFilter.Q.value = 0.55;
    const airGain = ctx.createGain();
    airGain.gain.value = 0.026;
    air.connect(airFilter);
    airFilter.connect(airGain);
    airGain.connect(amb);
    air.start();

    const airLfo = ctx.createOscillator();
    airLfo.frequency.value = 0.061;
    const airLfoGain = ctx.createGain();
    airLfoGain.gain.value = 0.014;
    airLfo.connect(airLfoGain);
    airLfoGain.connect(airGain.gain);
    airLfo.start();

    this.ambient = { amb, filter, oscs, air, airFilter, airGain, lfo, airLfo };
  }

  bus(pan = 0) {
    const ctx = this.ctx;
    const out = ctx.createGain();
    if (pan !== 0 && ctx.createStereoPanner) {
      const panner = ctx.createStereoPanner();
      panner.pan.value = Math.max(-1, Math.min(1, pan));
      out.connect(panner);
      panner.connect(this.dry);
      panner.connect(this.wet);
    } else {
      out.connect(this.dry);
      out.connect(this.wet);
    }
    return out;
  }

  tone({ freq = 220, endFreq = null, dur = 0.3, type = 'sine', vol = 0.1, pan = 0, attack = 0.005, detune = 0, delay = 0 }) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const start = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.detune.value = detune;
    osc.frequency.setValueAtTime(Math.max(20, freq), start);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), start + dur);
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), start + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + dur);
    osc.connect(gain);
    gain.connect(this.bus(pan));
    osc.start(start);
    osc.stop(start + dur + 0.02);
  }

  noise({ dur = 0.25, vol = 0.08, type = 'bandpass', freq = 900, endFreq = null, Q = 0.8, pan = 0, delay = 0 }) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const start = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = 0.8 + Math.random() * 0.4;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, start);
    if (endFreq) filter.frequency.exponentialRampToValueAtTime(Math.max(40, endFreq), start + dur);
    filter.Q.value = Q;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), start + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + dur);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.bus(pan));
    src.start(start);
    src.stop(start + dur + 0.05);
  }

  swing() {
    this.noise({ dur: 0.16, vol: 0.045, type: 'bandpass', freq: 620, endFreq: 240, Q: 0.7 });
  }

  hitOre(kind = 'ember', pan = 0) {
    const base = { ember: 196, gloam: 330, blood: 150, soul: 392 }[kind] || 196;
    this.noise({ dur: 0.09, vol: 0.075, type: 'highpass', freq: 1300, pan });
    this.tone({ freq: base * 2.4, endFreq: base * 1.7, dur: 0.11, type: 'triangle', vol: 0.055, pan });
    this.tone({ freq: base, endFreq: base * 0.72, dur: 0.14, type: 'square', vol: 0.022, pan });
  }

  breakOre(kind = 'ember', pan = 0) {
    const base = { ember: 196, gloam: 330, blood: 146, soul: 392 }[kind] || 196;
    this.noise({ dur: 0.38, vol: 0.14, type: 'lowpass', freq: 1600, endFreq: 220, Q: 0.7, pan });
    this.noise({ dur: 0.2, vol: 0.09, type: 'highpass', freq: 2400, pan });
    this.tone({ freq: base * 3, endFreq: base * 2, dur: 0.6, type: 'sine', vol: 0.07, pan });
    this.tone({ freq: base, endFreq: base * 0.5, dur: 0.4, type: 'triangle', vol: 0.04, pan });
  }

  pickup(kind = 'ember', pan = 0) {
    const base = { ember: 523, gloam: 659, blood: 392, soul: 784 }[kind] || 523;
    this.tone({ freq: base, dur: 0.09, type: 'sine', vol: 0.055, pan });
    this.tone({ freq: base * 1.5, dur: 0.14, type: 'sine', vol: 0.035, pan, delay: 0.055 });
  }

  hurt(pan = 0) {
    this.noise({ dur: 0.3, vol: 0.12, type: 'lowpass', freq: 900, endFreq: 180, pan });
    this.tone({ freq: 130, endFreq: 58, dur: 0.4, type: 'sawtooth', vol: 0.06, pan });
  }

  enemyHit(pan = 0) {
    this.noise({ dur: 0.14, vol: 0.1, type: 'bandpass', freq: 420, Q: 0.6, pan });
    this.tone({ freq: 180, endFreq: 90, dur: 0.16, type: 'square', vol: 0.035, pan });
  }

  enemyDeath(pan = 0) {
    this.tone({ freq: 300, endFreq: 42, dur: 0.9, type: 'sawtooth', vol: 0.045, pan });
    this.noise({ dur: 0.7, vol: 0.08, type: 'lowpass', freq: 1000, endFreq: 120, pan });
  }

  step(pan = 0, heavy = false) {
    this.noise({ dur: 0.09, vol: heavy ? 0.035 : 0.022, type: 'lowpass', freq: 380, endFreq: 190, pan });
  }

  upgrade() {
    const notes = [392, 523.25, 659.25, 783.99];
    notes.forEach((freq, i) => {
      this.tone({ freq, dur: 0.65, type: 'triangle', vol: 0.045, delay: i * 0.085 });
      this.tone({ freq: freq * 2, dur: 0.4, type: 'sine', vol: 0.018, delay: i * 0.085 });
    });
    this.noise({ dur: 0.8, vol: 0.05, type: 'bandpass', freq: 1600, endFreq: 500 });
  }

  denied(pan = 0) {
    this.tone({ freq: 110, endFreq: 82, dur: 0.35, type: 'square', vol: 0.035, pan });
    this.tone({ freq: 116.5, endFreq: 87, dur: 0.35, type: 'triangle', vol: 0.03, pan });
  }

  gateOpen() {
    this.tone({ freq: 55, dur: 2.2, type: 'sine', vol: 0.08 });
    this.tone({ freq: 82.4, dur: 1.8, type: 'triangle', vol: 0.045, delay: 0.2 });
    this.noise({ dur: 1.6, vol: 0.06, type: 'bandpass', freq: 240, endFreq: 900, Q: 1.2 });
  }

  descend() {
    this.tone({ freq: 45, endFreq: 28, dur: 1.8, type: 'sine', vol: 0.12 });
    this.noise({ dur: 1.5, vol: 0.08, type: 'lowpass', freq: 800, endFreq: 70 });
    [261.6, 311.1, 392].forEach((freq, i) => this.tone({ freq, dur: 1.4, type: 'triangle', vol: 0.025, delay: 0.25 + i * 0.12 }));
  }

  bossHit(pan = 0) {
    this.noise({ dur: 0.24, vol: 0.15, type: 'lowpass', freq: 1200, endFreq: 150, pan });
    this.tone({ freq: 98, endFreq: 44, dur: 0.5, type: 'sawtooth', vol: 0.06, pan });
    this.tone({ freq: 1046, endFreq: 700, dur: 0.4, type: 'sine', vol: 0.035, pan });
  }

  victory() {
    [261.63, 329.63, 392, 523.25, 659.25].forEach((freq, i) => {
      this.tone({ freq, dur: 3.2, type: 'sine', vol: 0.05, delay: i * 0.18 });
      this.tone({ freq: freq / 2, dur: 3.8, type: 'triangle', vol: 0.028, delay: i * 0.18 });
    });
    this.noise({ dur: 3.4, vol: 0.06, type: 'bandpass', freq: 600, endFreq: 2400, Q: 0.5 });
  }

  drip() {
    const pan = Math.random() * 1.6 - 0.8;
    const base = 700 + Math.random() * 800;
    this.tone({ freq: base, endFreq: base * 0.45, dur: 0.18, type: 'sine', vol: 0.022, pan });
    this.tone({ freq: base * 0.3, dur: 0.5, type: 'sine', vol: 0.012, pan, delay: 0.03 });
  }

  heartbeat() {
    this.tone({ freq: 58, endFreq: 38, dur: 0.18, type: 'sine', vol: 0.08 });
    this.tone({ freq: 52, endFreq: 34, dur: 0.16, type: 'sine', vol: 0.055, delay: 0.24 });
  }

  uiClick() {
    this.tone({ freq: 760, endFreq: 520, dur: 0.07, type: 'triangle', vol: 0.025 });
  }

  update(dt, { critical = false, playing = false } = {}) {
    if (!this.ctx || !this.enabled) return;
    this.dripTimer -= dt;
    if (this.dripTimer <= 0) {
      this.dripTimer = 5 + Math.random() * 11;
      if (playing) this.drip();
    }
    if (critical && playing) {
      this.heartTimer -= dt;
      if (this.heartTimer <= 0) {
        this.heartTimer = 1.05;
        this.heartbeat();
      }
    } else {
      this.heartTimer = 0;
    }
  }
}

import * as THREE from 'three';

const dummy = new THREE.Object3D();
const tmpColor = new THREE.Color();

export class SparkSystem {
  constructor(scene, capacity = 420) {
    this.capacity = capacity;
    this.particles = [];
    const geometry = new THREE.OctahedronGeometry(0.045, 0);
    const material = new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 0.95,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    this.mesh = new THREE.InstancedMesh(geometry, material, capacity);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 5;
    for (let i = 0; i < capacity; i += 1) {
      dummy.position.set(0, -999, 0);
      dummy.scale.setScalar(0.0001);
      dummy.updateMatrix();
      this.mesh.setMatrixAt(i, dummy.matrix);
    }
    this.mesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3);
    this.mesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
    scene.add(this.mesh);
    this.cursor = 0;
  }

  spawn({ position, velocity, color, life = 0.8, size = 1, gravity = -7, drag = 0.985, bounce = 0.3 }) {
    const index = this.cursor;
    this.cursor = (this.cursor + 1) % this.capacity;
    const particle = this.particles[index];
    const data = {
      x: position.x, y: position.y, z: position.z,
      vx: velocity.x, vy: velocity.y, vz: velocity.z,
      life, maxLife: life, size, gravity, drag, bounce,
      color: color instanceof THREE.Color ? color.clone() : new THREE.Color(color),
    };
    if (particle) Object.assign(particle, data);
    else this.particles[index] = data;
    this.mesh.setColorAt(index, data.color);
    this.mesh.instanceColor.needsUpdate = true;
  }

  burst(position, color, count = 12, { speed = 3, spread = 1, life = 0.8, size = 1, gravity = -7, up = 1.2 } = {}) {
    for (let i = 0; i < count; i += 1) {
      const angle = Math.random() * Math.PI * 2;
      const power = speed * (0.35 + Math.random() * 0.8);
      this.spawn({
        position,
        velocity: {
          x: Math.cos(angle) * power * spread,
          y: up * (0.4 + Math.random() * 1.4),
          z: Math.sin(angle) * power * spread,
        },
        color,
        life: life * (0.55 + Math.random() * 0.65),
        size: size * (0.6 + Math.random() * 0.9),
        gravity,
      });
    }
  }

  update(dt) {
    const now = performance.now();
    const { capacity } = this;
    for (let i = 0; i < capacity; i += 1) {
      const p = this.particles[i];
      if (!p || p.life <= 0) {
        if (p && p.life > -999) {
          dummy.position.set(0, -999, 0);
          dummy.scale.setScalar(0.0001);
          dummy.rotation.set(0, 0, 0);
          dummy.updateMatrix();
          this.mesh.setMatrixAt(i, dummy.matrix);
          p.life = -1000;
        }
        continue;
      }
      p.life -= dt;
      if (p.life <= 0) {
        dummy.position.set(0, -999, 0);
        dummy.scale.setScalar(0.0001);
        dummy.updateMatrix();
        this.mesh.setMatrixAt(i, dummy.matrix);
        continue;
      }
      p.vy += p.gravity * dt;
      const drag = Math.pow(p.drag, dt * 60);
      p.vx *= drag;
      p.vy *= drag;
      p.vz *= drag;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;
      if (p.y < 0.02) {
        p.y = 0.02;
        p.vy = Math.abs(p.vy) * p.bounce;
        p.vx *= 0.68;
        p.vz *= 0.68;
        if (Math.abs(p.vy) < 0.12) p.vy = 0;
      }
      const ratio = Math.max(0, p.life / p.maxLife);
      const scale = p.size * (0.25 + ratio * 0.95);
      dummy.position.set(p.x, p.y, p.z);
      dummy.rotation.set(now * 0.001 + i, now * 0.0015 + i, 0);
      dummy.scale.setScalar(scale);
      dummy.updateMatrix();
      this.mesh.setMatrixAt(i, dummy.matrix);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
  }
}

export class MoteField {
  constructor(scene, texture, count, { color = 0xffc68a, size = 0.075, opacity = 0.55, area = 27, height = 13 } = {}) {
    this.count = count;
    this.area = area;
    this.height = height;
    const positions = new Float32Array(count * 3);
    this.speeds = new Float32Array(count);
    this.phases = new Float32Array(count);
    for (let i = 0; i < count; i += 1) {
      positions[i * 3] = (Math.random() - 0.5) * area * 2;
      positions[i * 3 + 1] = Math.random() * height + 0.2;
      positions[i * 3 + 2] = (Math.random() - 0.5) * area * 2;
      this.speeds[i] = 0.08 + Math.random() * 0.22;
      this.phases[i] = Math.random() * Math.PI * 2;
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const material = new THREE.PointsMaterial({
      size,
      map: texture,
      color,
      transparent: true,
      opacity,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
      toneMapped: false,
    });
    this.points = new THREE.Points(geometry, material);
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.material = material;
    this.positions = positions;
  }

  update(dt, time) {
    const pos = this.positions;
    for (let i = 0; i < this.count; i += 1) {
      const idx = i * 3;
      pos[idx + 1] += this.speeds[i] * dt;
      pos[idx] += Math.sin(time * 0.23 + this.phases[i]) * dt * 0.14;
      pos[idx + 2] += Math.cos(time * 0.19 + this.phases[i] * 1.3) * dt * 0.12;
      if (pos[idx + 1] > this.height) {
        pos[idx + 1] = 0.2;
        pos[idx] = (Math.random() - 0.5) * this.area * 2;
        pos[idx + 2] = (Math.random() - 0.5) * this.area * 2;
      }
    }
    this.points.geometry.attributes.position.needsUpdate = true;
  }

  dispose() {
    this.points.geometry.dispose();
    this.material.dispose();
    this.points.removeFromParent();
  }
}

export function sparkColor(hex, boost = 1) {
  tmpColor.setHex(hex);
  tmpColor.multiplyScalar(boost);
  return tmpColor.clone();
}
